17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Objects;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final AddressNormalizer addressNormalizer;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper,
75	                                 AddressNormalizer addressNormalizer) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	        this.addressNormalizer = addressNormalizer;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String address = addressNormalizer.normalize(owner.getAddress());
114	        if (address.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        owner.setAddress(address);
118	        String telephone = toE164(owner.getTelephone());
119	        if (telephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setTelephone(telephone);
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        if (isTelephoneInUse(telephone)) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
131	            return new ResponseEntity<>(HttpStatus.CONFLICT);
132	        }
133	        if (sharesHousehold) {
134	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
135	        }
136	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
137	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
138	        this.clinicService.saveOwner(owner);
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        headers.setLocation(UriComponentsBuilder.newInstance()
141	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
142	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
143	    }
144	
145	    /**
146	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
147	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
148	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
149	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
150	     */
151	    private String nextCustomerCode(String city, String lastName) {
152	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
153	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
154	        int sequence = (int) this.clinicService.findAllOwners().stream()
155	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
156	            .count() + 1;
157	        return String.format("%s-%s-%04d", city3, last3, sequence);
158	    }
159	
160	    /**
161	     * The number of existing owners that already share the given firstName and lastName,
162	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
163	     * whitespace runs collapsed). Counted over the owners present before this create.
164	     */
165	    private int namesakeCount(String firstName, String lastName) {
166	        String candidateFirstName = normalizeName(firstName);
167	        String candidateLastName = normalizeName(lastName);
168	        return (int) this.clinicService.findAllOwners().stream()
169	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
170	                && normalizeName(existing.getLastName()).equals(candidateLastName))
171	            .count();
172	    }
173	
174	    /**
175	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
176	     * cannot form a valid E.164 number.
177	     *
178	     * <p>A leading '+' and country code are kept when present; otherwise country code
179	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
180	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
181	     * carry 8 to 15 digits after the '+'.
182	     */
183	    private String toE164(String telephone) {
184	        if (telephone == null) {
185	            return null;
186	        }
187	        boolean hasCountryCode = telephone.trim().startsWith("+");
188	        String digits = telephone.replaceAll("\\D", "");
189	        String e164;
190	        if (hasCountryCode) {
191	            e164 = digits;
192	        } else {
193	            if (digits.startsWith("0")) {
194	                digits = digits.substring(1);
195	            }
196	            e164 = "61" + digits;
197	        }
198	        if (e164.length() < 8 || e164.length() > 15) {
199	            return null;
200	        }
201	        return "+" + e164;
202	    }
203	
204	    /**
205	     * Whether any existing owner already holds the given telephone number. Both the
206	     * candidate and each stored number are compared in E.164 form, so the check does not
207	     * depend on how each was originally formatted.
208	     */
209	    private boolean isTelephoneInUse(String telephone) {
210	        return this.clinicService.findAllOwners().stream()
211	            .map(Owner::getTelephone)
212	            .filter(Objects::nonNull)
213	            .map(this::toE164)
214	            .filter(Objects::nonNull)
215	            .anyMatch(telephone::equals);
216	    }
217	
218	    /**
219	     * Whether any existing owner already shares a household with the candidate, i.e. has both
220	     * the same lastName and the same address. Both fields are compared case-insensitively and
221	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
222	     * trimmed), so the check does not depend on casing or spacing.
223	     */
224	    private boolean isHouseholdInUse(String lastName, String address) {
225	        String candidateLastName = normalizeName(lastName);
226	        String candidateAddress = addressNormalizer.normalize(address);
227	        return this.clinicService.findAllOwners().stream()
228	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
229	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
230	    }
231	
232	    /**
233	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
234	     * to a single space and lower-case. A null value normalizes to the empty string.
235	     */
236	    private String normalizeName(String value) {
237	        if (value == null) {
238	            return "";
239	        }
240	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
241	    }
242	
243	    /**
244	     * A stable shared identifier for the household formed by a given lastName and address.
245	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
246	     * lastName and address, so every owner sharing the same household is assigned the same
247	     * value regardless of the order in which they are created. Formatted as the first 12
248	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
249	     */
250	    private String householdId(String lastName, String address) {
251	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
252	        try {
253	            byte[] digest = MessageDigest.getInstance("SHA-256")
254	                .digest(key.getBytes(StandardCharsets.UTF_8));
255	            StringBuilder sb = new StringBuilder(digest.length * 2);
256	            for (byte b : digest) {
257	                sb.append(String.format("%02x", b));
258	            }
259	            return sb.substring(0, 12).toUpperCase();
260	        }
261	        catch (NoSuchAlgorithmException e) {
262	            throw new IllegalStateException("SHA-256 not available", e);
263	        }
264	    }
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
269	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
270	        if (currentOwner == null) {
271	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	        }
273	        currentOwner.setAddress(ownerFieldsDto.getAddress());
274	        currentOwner.setCity(ownerFieldsDto.getCity());
275	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
276	        currentOwner.setLastName(ownerFieldsDto.getLastName());
277	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
278	        this.clinicService.saveOwner(currentOwner);
279	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
280	    }
281	
282	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
283	    @Transactional
284	    @Override
285	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
286	        Owner owner = this.clinicService.findOwnerById(ownerId);
287	        if (owner == null) {
288	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	        }
290	        this.clinicService.deleteOwner(owner);
291	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
292	    }
293	
294	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
295	    @Override
296	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
297	        Owner owner = this.clinicService.findOwnerById(ownerId);
298	        if (owner == null) {
299	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	        }
301	        HttpHeaders headers = new HttpHeaders();
302	        Pet pet = petMapper.toPet(petFieldsDto);
303	        owner.setId(ownerId);
304	        pet.setOwner(owner);
305	        pet.getType().setName(null);
306	        this.clinicService.savePet(pet);
307	        PetDto petDto = petMapper.toPetDto(pet);
308	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
309	            .buildAndExpand(pet.getId()).toUri());
310	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
311	    }
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
316	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
317	        if (currentOwner != null) {
318	            Pet currentPet = this.clinicService.findPetById(petId);
319	            if (currentPet != null) {
320	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
321	                currentPet.setName(petFieldsDto.getName());
322	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
323	                this.clinicService.savePet(currentPet);
324	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
325	            }
326	        }
327	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
328	    }
329	
330	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
331	    @Override
332	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
333	        HttpHeaders headers = new HttpHeaders();
334	        Visit visit = visitMapper.toVisit(visitFieldsDto);
335	        Pet pet = new Pet();
336	        pet.setId(petId);
337	        visit.setPet(pet);
338	        this.clinicService.saveVisit(visit);
339	        VisitDto visitDto = visitMapper.toVisitDto(visit);
340	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
341	            .buildAndExpand(visit.getId()).toUri());
342	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
343	    }
344	
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
349	        Owner owner = this.clinicService.findOwnerById(ownerId);
350	        if (owner != null) {
351	            Pet pet = owner.getPet(petId);
352	            if (pet != null) {
353	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
354	            }
355	        }
356	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
357	    }
358	}
